public with sharing class ContactDomainService {

    /**
     * Groups the contacts of the given accounts by the lower-cased domain
     * part of their email address. Contacts without an email are excluded.
     *
     * @param accountIds the parent account ids; null or empty returns an empty map
     * @return map of lower-cased email domain -> contacts with Id, Email and AccountId populated
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact con : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            Integer atIndex = con.Email.indexOf('@');
            if (atIndex < 0 || atIndex == con.Email.length() - 1) {
                continue;
            }

            String domain = con.Email.substring(atIndex + 1).toLowerCase();

            List<Contact> domainContacts = contactsByDomain.get(domain);
            if (domainContacts == null) {
                domainContacts = new List<Contact>();
                contactsByDomain.put(domain, domainContacts);
            }
            domainContacts.add(con);
        }

        return contactsByDomain;
    }
}
