public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // --- Validate maxRows ---
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // --- Validate fields list ---
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // --- Resolve object (case-insensitive) ---
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }
        Schema.DescribeSObjectResult objDescribe = null;
        for (Schema.SObjectType t : Schema.getGlobalDescribe().values()) {
            Schema.DescribeSObjectResult d = t.getDescribe();
            if (d.getName().equalsIgnoreCase(objectApiName.trim())) {
                objDescribe = d;
                break;
            }
        }
        if (objDescribe == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        if (!objDescribe.isAccessible()) {
            throw new SearchException(
                'You do not have read access to object: ' + objDescribe.getName());
        }

        // Case-insensitive field map
        Map<String, Schema.DescribeFieldResult> fieldMap =
            new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField f : objDescribe.fields.getMap().values()) {
            Schema.DescribeFieldResult d = f.getDescribe();
            fieldMap.put(d.getName().toLowerCase(), d);
        }

        // --- Validate requested fields ---
        Set<String> selectNames = new Set<String>{ 'Id' };
        for (String fld : fields) {
            Schema.DescribeFieldResult d = resolveField(fieldMap, fld);
            if (!d.isAccessible()) {
                throw new SearchException(
                    'You do not have read access to field: ' + d.getName());
            }
            selectNames.add(d.getName());
        }

        // --- Validate filters ---
        List<String> filterFieldNames = new List<String>();
        Map<String, Object> bindValues = new Map<String, Object>();
        if (filters != null) {
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult d = resolveField(fieldMap, key);
                if (!d.isAccessible()) {
                    throw new SearchException(
                        'You do not have read access to field: ' + d.getName());
                }
                if (!d.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be filtered: ' + d.getName());
                }
                filterFieldNames.add(d.getName());
                bindValues.put(d.getName(), filters.get(key));
            }
        }

        // --- Validate order-by field ---
        String orderByName = null;
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult d = resolveField(fieldMap, orderByField);
            if (!d.isAccessible()) {
                throw new SearchException(
                    'You do not have read access to field: ' + d.getName());
            }
            if (!d.isSortable()) {
                throw new SearchException(
                    'Field cannot be sorted: ' + d.getName());
            }
            orderByName = d.getName();
        }

        // --- Build the query ---
        String soql = 'SELECT ' + String.join(new List<String>(selectNames), ', ')
            + ' FROM ' + String.escapeSingleQuotes(objDescribe.getName());

        Map<String, Object> queryBinds = new Map<String, Object>();
        if (!filterFieldNames.isEmpty()) {
            List<String> conditions = new List<String>();
            for (Integer i = 0; i < filterFieldNames.size(); i++) {
                String bindKey = 'filterValue' + i;
                conditions.add(filterFieldNames[i] + ' = :' + bindKey);
                queryBinds.put(bindKey, bindValues.get(filterFieldNames[i]));
            }
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }
        if (orderByName != null) {
            soql += ' ORDER BY ' + orderByName + ' ASC';
        }
        soql += ' LIMIT :rowLimit';
        queryBinds.put('rowLimit', maxRows);

        // USER_MODE enforces record sharing and field-level security.
        try {
            return Database.queryWithBinds(
                soql, queryBinds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult resolveField(
        Map<String, Schema.DescribeFieldResult> fieldMap, String name
    ) {
        if (String.isBlank(name)
                || !fieldMap.containsKey(name.trim().toLowerCase())) {
            throw new SearchException('Unknown field: ' + name);
        }
        return fieldMap.get(name.trim().toLowerCase());
    }
}
