/**
 * Invocable action for Flow: finds an existing Contact by email address.
 * Bulk-safe: one SOQL query per call, one Result per Request in request order.
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;
        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        Set<String> emails = new Set<String>();

        for (Request req : requests) {
            String normalized = req.email == null ? '' : req.email.trim().toLowerCase();
            if (String.isNotBlank(normalized)) {
                emails.add(normalized);
            }
            Result res = new Result();
            res.found = false;
            res.contactId = null;
            results.add(res);
        }

        Map<String, Contact> earliestByEmail = new Map<String, Contact>();
        if (!emails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emails
                ORDER BY CreatedDate ASC
            ]) {
                String key = c.Email.toLowerCase();
                // First record per email in CreatedDate ASC order is the earliest.
                if (!earliestByEmail.containsKey(key)) {
                    earliestByEmail.put(key, c);
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalized = requests[i].email == null
                ? ''
                : requests[i].email.trim().toLowerCase();
            if (String.isNotBlank(normalized)) {
                Contact match = earliestByEmail.get(normalized);
                if (match != null) {
                    results[i].contactId = match.Id;
                    results[i].found = true;
                }
            }
        }

        return results;
    }
}
