public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body must not be null or blank.');
        }

        Object raw;
        try {
            raw = JSON.deserializeUntyped(body);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON: ' + e.getMessage());
        }

        if (!(raw instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object.');
        }
        Map<String, Object> root = (Map<String, Object>) raw;

        Order ord = new Order();

        String number = toText(root.get('number'));
        if (String.isBlank(number)) {
            throw new PayloadException('Missing or blank "number".');
        }
        ord.orderNumber = number;

        String dateStr = toText(root.get('date'));
        if (String.isNotBlank(dateStr)) {
            try {
                ord.orderDate = Date.valueOf(dateStr);
            } catch (PayloadException pe) {
                throw pe;
            } catch (Exception e) {
                throw new PayloadException('Invalid "date" value, expected yyyy-MM-dd: ' + dateStr);
            }
        }

        ord.currencyCode = toText(root.get('currency'));

        Object customerRaw = root.get('customer');
        if (customerRaw instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) customerRaw;
            ord.customerEmail = toText(customer.get('email'));
        }

        ord.lines = new List<Line>();
        Object linesRaw = root.get('lines');
        if (linesRaw != null) {
            if (!(linesRaw instanceof List<Object>)) {
                throw new PayloadException('"lines" must be an array.');
            }
            for (Object lineRaw : (List<Object>) linesRaw) {
                ord.lines.add(parseLine(lineRaw));
            }
        }

        Decimal total = 0;
        for (Line l : ord.lines) {
            total += l.lineTotal;
        }
        ord.total = total;

        return ord;
    }

    private static Line parseLine(Object lineRaw) {
        if (!(lineRaw instanceof Map<String, Object>)) {
            throw new PayloadException('Each line must be a JSON object.');
        }
        Map<String, Object> lineMap = (Map<String, Object>) lineRaw;

        Line line = new Line();

        String sku = toText(lineMap.get('sku'));
        if (String.isBlank(sku)) {
            throw new PayloadException('Line is missing "sku".');
        }
        line.sku = sku;

        Decimal qty = toDecimal(lineMap.get('quantity'));
        if (qty == null || qty <= 0) {
            throw new PayloadException('Line "' + sku + '" has a missing or non-positive "quantity".');
        }
        line.quantity = qty.intValue();

        Decimal price = toDecimal(lineMap.get('unitPrice'));
        if (price == null || price < 0) {
            throw new PayloadException('Line "' + sku + '" has a missing or negative "unitPrice".');
        }
        line.unitPrice = price;

        Decimal discount = toDecimal(lineMap.get('discount'));
        if (discount == null) {
            discount = 0;
        }
        if (discount < 0 || discount > 1) {
            throw new PayloadException('Line "' + sku + '" has an invalid "discount" (must be between 0 and 1).');
        }
        line.discount = discount;

        line.lineTotal = (qty * price * (1 - discount)).setScale(2, RoundingMode.HALF_UP);

        return line;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null) {
            throw new PayloadException('Order must not be null.');
        }
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines == null ? 0 : order.lines.size(),
            'total' => order.total == null ? 0 : order.total
        };
        return JSON.serialize(ack);
    }

    private static String toText(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        if (value instanceof String) {
            String s = ((String) value).trim();
            if (s == '') {
                return null;
            }
            try {
                return Decimal.valueOf(s);
            } catch (PayloadException pe) {
                throw pe;
            } catch (Exception e) {
                throw new PayloadException('Value is not a valid number: ' + s);
            }
        }
        throw new PayloadException('Value is not a number: ' + String.valueOf(value));
    }
}
