/**
 * Utility for retrieving the active values of any picklist field, chosen at runtime.
 */
public class PicklistService {

    /**
     * Returns the active values of the given picklist or multi-select picklist field,
     * in the order they are defined on the field.
     *
     * @param objectApiName API name of the object (case-insensitive, standard or custom)
     * @param fieldApiName  API name of the field (case-insensitive)
     * @return active options in defined order
     * @throws PicklistServiceException when the names are blank, the object or field
     *         does not exist, or the field is not a picklist / multi-select picklist
     */
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        String objectName = objectApiName.trim();
        String fieldName = fieldApiName.trim();

        Schema.DescribeSObjectResult objectDescribe = null;
        try {
            objectDescribe = Schema.describeSObjects(new List<String>{ objectName })[0];
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Object "' + objectName + '" does not exist or is not accessible.', e
            );
        }
        if (objectDescribe == null) {
            throw new PicklistServiceException(
                'Object "' + objectName + '" does not exist or is not accessible.'
            );
        }

        // Field map keys are lowercase, so this lookup is case-insensitive.
        Schema.SObjectField field = objectDescribe.fields.getMap().get(fieldName.toLowerCase());
        if (field == null) {
            throw new PicklistServiceException(
                'Field "' + fieldName + '" does not exist on object "' + objectName + '".'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST
                && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field "' + fieldName + '" on object "' + objectName
                + '" is not a picklist or multi-select picklist.'
            );
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            PicklistService.Option option = new PicklistService.Option();
            option.value = entry.getValue();
            option.label = entry.getLabel();
            option.isDefault = entry.isDefaultValue();
            options.add(option);
        }
        return options;
    }

    /** A single active picklist option. */
    public class Option {
        /** API value of the option. */
        public String value;
        /** Display label of the option. */
        public String label;
        /** True only for the field's default value. */
        public Boolean isDefault;
    }

    /** Thrown for any invalid input or unsupported field in PicklistService. */
    public class PicklistServiceException extends Exception {
    }
}
