```apex
public class OpportunityPipelineHandler {

    // Guards against infinite recursion:
    // recalculate() updates Accounts -> AccountTrigger updates open Opportunities
    // -> OpportunityTrigger fires again. The guard lets that nested invocation
    // exit immediately (amounts/stages did not change, only FB_Account_Rating__c).
    // The flag is reset in a finally block at the end of every invocation, so
    // subsequent, unrelated DML in the same transaction is processed normally.
    private static Boolean isRunning = false;

    public static void recalculate(Set<Id> accountIds) {
        if (isRunning || accountIds == null || accountIds.isEmpty()) {
            return;
        }

        isRunning = true;
        try {
            // Start from 0/0 for every affected account so that an account whose
            // last open opportunity went away ends up with zeros, not blanks.
            Map<Id, Account> recalculated = new Map<Id, Account>();
            for (Id accountId : accountIds) {
                recalculated.put(accountId, new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = 0,
                    FB_Open_Opportunities__c = 0
                ));
            }

            // SUM(Amount) ignores null Amounts, so blank amounts count as 0.
            for (AggregateResult ar : [
                SELECT AccountId accountId, SUM(Amount) totalAmount, COUNT(Id) openCount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
                GROUP BY AccountId
            ]) {
                Id accountId = (Id) ar.get('accountId');
                Decimal totalAmount = (Decimal) ar.get('totalAmount');
                recalculated.put(accountId, new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = totalAmount == null ? 0 : totalAmount,
                    FB_Open_Opportunities__c = (Integer) ar.get('openCount')
                ));
            }

            // Only write accounts whose values actually changed. This avoids
            // needless Account DML (and therefore needless AccountTrigger /
            // opportunity rating-sync churn) when a trigger pass did not
            // affect any totals.
            List<Account> toUpdate = new List<Account>();
            for (Account current : [
                SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
                FROM Account
                WHERE Id IN :accountIds
            ]) {
                Account next = recalculated.get(current.Id);
                if (current.FB_Open_Pipeline__c != next.FB_Open_Pipeline__c
                        || current.FB_Open_Opportunities__c != next.FB_Open_Opportunities__c) {
                    toUpdate.add(next);
                }
            }

            if (!toUpdate.isEmpty()) {
                update toUpdate;
            }
        } finally {
            isRunning = false;
        }
    }
}
