```apex
public with sharing class PipelineSummary {

    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the summed Amount of open Opportunities per managed stage,
     * for CloseDate between fromDate and toDate inclusive.
     * Stages with no matching Opportunities map to 0, never null.
     *
     * Implementation note: one aggregate query per stage, exactly four queries
     * total regardless of data volume, as requested. An equivalent single-query
     * alternative would be one GROUP BY StageName aggregate over all four
     * stages (with the stage names filtered via the IN operator); that would
     * use one query instead of four, but requires bucketing the results into
     * the fixed key set afterwards. Both approaches are bulk-safe here since
     * the number of queries is constant and tiny.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : STAGES) {
            AggregateResult result = [
                SELECT SUM(Amount) total
                FROM Opportunity
                WHERE StageName = :stage
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            ];

            Decimal total = (Decimal) result.get('total');
            totals.put(stage, total == null ? 0 : total);
        }

        return totals;
    }
}
