    /**
     * Sets the standard discount on new lines that don't already have one.
     * Lines with an explicit Discount value (including 0) are left untouched.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        // Collect the products we need standard discounts for.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }
        if (productIds.isEmpty()) {
            return;
        }

        // One bulk query for all products, then delegate the discount logic
        // to PricingRules so the rules stay in a single place.
        Map<Id, Product2> products = new Map<Id, Product2>(
            [SELECT Family FROM Product2 WHERE Id IN :productIds]
        );

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                Product2 product = products.get(line.Product2Id);
                if (product != null) {
                    line.Discount = PricingRules.standardDiscountForFamily(product.Family);
                }
            }
        }
    }
}
