import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;
    _loading = false;
    _intervalId;
    _boundVisibilityHandler;

    connectedCallback() {
        this._boundVisibilityHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._boundVisibilityHandler);
        this.loadStats();
        this.startPolling();
    }

    disconnectedCallback() {
        this.stopPolling();
        if (this._boundVisibilityHandler) {
            document.removeEventListener('visibilitychange', this._boundVisibilityHandler);
            this._boundVisibilityHandler = undefined;
        }
    }

    startPolling() {
        this.stopPolling();
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            // Load immediately and restart the 60s cadence so there is
            // only ever one polling loop.
            this.loadStats();
            this.startPolling();
        }
    }

    async loadStats() {
        if (this._loading) {
            return;
        }
        if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
            return;
        }
        this._loading = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats ? stats.waiting : undefined;
            this.longestWaitMinutes = stats ? stats.longestWaitMinutes : undefined;
            this.hasStats = true;
            this.errorMessage = undefined;
        } catch (error) {
            this.errorMessage =
                error?.body?.message ??
                (Array.isArray(error?.body) ? error.body.map((e) => e.message).join(', ') : undefined) ??
                error?.message ??
                'Unknown error';
        } finally {
            this._loading = false;
        }
    }
}
