import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _label = '';
    _options = [];
    _value = '';
    _activeValue;

    @api
    get label() {
        return this._label;
    }
    set label(v) {
        this._label = v ?? '';
    }

    @api
    get options() {
        return this._options;
    }
    set options(v) {
        this._options = Array.isArray(v) ? v : [];
        this.syncActiveOnOptionsChange();
    }

    @api
    get value() {
        return this._value;
    }
    set value(v) {
        const newVal = v ?? '';
        this._value = newVal;
        this.syncActiveToValue(newVal);
    }

    syncActiveToValue(newVal) {
        const opts = this._options || [];
        if (opts.length === 0) {
            this._activeValue = undefined;
            return;
        }
        if (newVal) {
            const found = opts.some((o) => o && o.value === newVal);
            if (found) {
                this._activeValue = newVal;
                return;
            }
            // Value not in options: keep current active if still valid, else first
            const activeValid = opts.some((o) => o && o.value === this._activeValue);
            if (!activeValid) {
                this._activeValue = opts[0].value;
            }
            return;
        }
        // Empty value -> active is first option
        this._activeValue = opts[0].value;
    }

    syncActiveOnOptionsChange() {
        const opts = this._options || [];
        if (opts.length === 0) {
            this._activeValue = undefined;
            return;
        }
        if (this._value) {
            const found = opts.some((o) => o && o.value === this._value);
            if (found) {
                this._activeValue = this._value;
                return;
            }
        } else {
            // Nothing selected -> first option
            this._activeValue = opts[0].value;
            return;
        }
        // Selected value not present; keep active if still valid else first
        const activeValid = opts.some((o) => o && o.value === this._activeValue);
        if (!activeValid) {
            this._activeValue = opts[0].value;
        }
    }

    ensureActive() {
        const opts = this._options || [];
        if (opts.length === 0) {
            return;
        }
        const valid = opts.some((o) => o && o.value === this._activeValue);
        if (!valid) {
            if (this._value && opts.some((o) => o && o.value === this._value)) {
                this._activeValue = this._value;
            } else {
                this._activeValue = opts[0].value;
            }
        }
    }

    get items() {
        const opts = this._options || [];
        return opts.map((opt, index) => {
            const val = opt ? opt.value : '';
            const lbl = opt ? opt.label : '';
            return {
                key: `${index}-${val}`,
                value: val,
                label: lbl,
                id: `status-option-${index}`,
                selected: val === this._value ? 'true' : 'false'
            };
        });
    }

    get activeOptionId() {
        const opts = this._options || [];
        if (opts.length === 0) {
            return undefined;
        }
        let idx = opts.findIndex((o) => o && o.value === this._activeValue);
        if (idx === -1) {
            idx = 0;
        }
        return `status-option-${idx}`;
    }

    get activeIndex() {
        const opts = this._options || [];
        const idx = opts.findIndex((o) => o && o.value === this._activeValue);
        return idx === -1 ? 0 : idx;
    }

    setActiveIndex(idx) {
        const opts = this._options || [];
        if (opts.length === 0) {
            return;
        }
        const clamped = Math.max(0, Math.min(idx, opts.length - 1));
        this._activeValue = opts[clamped].value;
    }

    handleKeydown(event) {
        const key = event.key;
        const opts = this._options || [];
        if (opts.length === 0) {
            return;
        }
        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                this.ensureActive();
                this.setActiveIndex(this.activeIndex + 1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.ensureActive();
                this.setActiveIndex(this.activeIndex - 1);
                break;
            case 'Home':
                event.preventDefault();
                this.setActiveIndex(0);
                break;
            case 'End':
                event.preventDefault();
                this.setActiveIndex(opts.length - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.ensureActive();
                this.selectOption(this._activeValue);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const el = event.currentTarget;
        const val = el ? el.getAttribute('data-value') : null;
        // Fallback via dataset
        const resolved = val !== null && val !== undefined ? val : el?.dataset?.value;
        this.selectOption(resolved);
        // Clicking makes it the active option even if already selected
        const opts = this._options || [];
        if (opts.some((o) => o && o.value === resolved)) {
            this._activeValue = resolved;
        }
    }

    selectOption(val) {
        if (val === undefined) {
            return;
        }
        if (val === this._value) {
            // Still ensure active reflects it
            return;
        }
        this._value = val;
        this._activeValue = val;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: val },
                bubbles: true,
                composed: true
            })
        );
    }
}
