public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> toInsert = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            if (g != null) {
                di.npsp__Contact1_Firstname__c = g.firstName;
                di.npsp__Contact1_Lastname__c = g.lastName;
                di.npsp__Contact1_Personal_Email__c = g.email;
                di.npsp__Donation_Amount__c = g.amount;
                di.npsp__Donation_Date__c = g.giftDate;
                di.npsp__Donation_Donor__c = 'Contact1';
            }
            toInsert.add(di);
            ImportResult r = new ImportResult();
            r.success = false;
            results.add(r);
        }

        Database.SaveResult[] saveResults = Database.insert(toInsert, false);

        // Collect successfully inserted rows and map index -> record
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        Map<Integer, Id> indexToId = new Map<Integer, Id>();
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult sr = saveResults[i];
            if (sr.isSuccess()) {
                indexToId.put(i, sr.getId());
                // Re-query shape not needed; API needs Id at minimum but pass full record
                toProcess.add(new npsp__DataImport__c(Id = sr.getId()));
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error e : sr.getErrors()) {
                    msgs.add(e.getMessage());
                }
                results[i].success = false;
                results[i].errorMessage = String.join(msgs, '; ');
            }
        }

        if (!toProcess.isEmpty()) {
            npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getInstance();
            if (diSettings == null) {
                diSettings = new npsp__Data_Import_Settings__c();
            }
            try {
                npsp.BDI_DataImport_API.processDataImportRecords(diSettings, toProcess, false);
            } catch (Exception e) {
                // Whole batch threw - mark every processable row failed unless already resolved
                for (Integer idx : indexToId.keySet()) {
                    if (results[idx].errorMessage == null && results[idx].contactId == null && results[idx].opportunityId == null && results[idx].success == false) {
                        // Only overwrite if not already set from insert failure (those idx not in map)
                        results[idx].success = false;
                        results[idx].errorMessage = e.getMessage();
                    }
                }
                // Attempt to refresh statuses anyway in case some rows were updated before throw
                toProcess.clear();
                // fall through to query to overwrite with actual statuses where available
                List<Id> ids = indexToId.values();
                Map<Id, npsp__DataImport__c> processed = queryImports(ids);
                for (Integer idx : indexToId.keySet()) {
                    npsp__DataImport__c rec = processed.get(indexToId.get(idx));
                    if (rec != null && rec.npsp__Status__c == 'Imported') {
                        results[idx].success = true;
                        results[idx].contactId = rec.npsp__Contact1Imported__c;
                        results[idx].opportunityId = rec.npsp__DonationImported__c;
                        results[idx].errorMessage = null;
                    } else if (rec != null && results[idx].errorMessage == null) {
                        results[idx].errorMessage = rec.npsp__FailureInformation__c;
                    }
                }
                return results;
            }

            // Re-query processed records for results
            List<Id> ids = new List<Id>(indexToId.values());
            Map<Id, npsp__DataImport__c> processed = queryImports(ids);
            for (Integer idx : indexToId.keySet()) {
                Id diId = indexToId.get(idx);
                npsp__DataImport__c rec = processed.get(diId);
                if (rec == null) {
                    results[idx].success = false;
                    results[idx].errorMessage = 'Data Import record not found after processing.';
                    continue;
                }
                Boolean imported = rec.npsp__Status__c == 'Imported';
                // Fallback: consider imported if donation/contact populated and status indicates success
                results[idx].success = imported;
                results[idx].contactId = rec.npsp__Contact1Imported__c;
                results[idx].opportunityId = rec.npsp__DonationImported__c;
                if (imported) {
                    results[idx].errorMessage = null;
                } else {
                    results[idx].errorMessage = rec.npsp__FailureInformation__c;
                }
            }
        }

        return results;
    }

    private static Map<Id, npsp__DataImport__c> queryImports(List<Id> ids) {
        Map<Id, npsp__DataImport__c> m = new Map<Id, npsp__DataImport__c>();
        if (ids == null || ids.isEmpty()) {
            return m;
        }
        for (npsp__DataImport__c rec : [
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :ids
        ]) {
            m.put(rec.Id, rec);
        }
        return m;
    }
}
