public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // Validate opportunity
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        // Validate map null or empty
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Allocation map must not be null or empty.');
        }

        // Validate percentages: null or not greater than 0
        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each percentage must be greater than 0.');
            }
            if (gauId == null) {
                throw new AllocationException('GAU Id must not be null.');
            }
            total += pct;
        }

        // Validate total > 100
        if (total > 100) {
            throw new AllocationException('Percentages add up to more than 100%.');
        }

        // Validate Opportunity exists
        List<Opportunity> opps = [SELECT Id FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity not found.');
        }

        // Validate GAUs exist and are active
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :gauIds]
        );
        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU not found: ' + gauId);
            }
            if (gau.npsp__Active__c == false) {
                throw new AllocationException('GAU is inactive: ' + gauId);
            }
        }

        // All validation passed — now modify data.
        // Replace all existing allocations for this Opportunity.
        List<npsp__Allocation__c> existingAllos = [
            SELECT Id FROM npsp__Allocation__c WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllos.isEmpty()) {
            delete existingAllos;
        }

        // Create one allocation per map entry using Percent (not Amount)
        // so NPSP keeps Amounts in sync when Opportunity Amount changes.
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            npsp__Allocation__c allo = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            );
            toInsert.add(allo);
        }
        insert toInsert;

        // Re-query to return fully populated records (Amounts calculated by NPSP)
        List<npsp__Allocation__c> inserted = [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c, npsp__Amount__c, npsp__Percent__c
            FROM npsp__Allocation__c
            WHERE Id IN :toInsert
        ];
        return inserted;
    }
}
