public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact');
        }

        // Insert the first Contact without an Account so NPSP automatically
        // creates ONE new Household Account (HH_Account record type) for it.
        // We do not create the Account ourselves and do not set any Account Name,
        // so NPSP household naming and greetings are generated.
        Contact firstMember = members[0];
        firstMember.AccountId = null;
        insert firstMember;

        // Re-query to get the NPSP-created Household Account Id reliably.
        firstMember = [SELECT Id, AccountId FROM Contact WHERE Id = :firstMember.Id LIMIT 1];
        Id householdId = firstMember.AccountId;

        // Insert any remaining members directly into that same household,
        // so no additional/empty households are created.
        if (members.size() > 1) {
            List<Contact> restMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdId;
                restMembers.add(c);
            }
            insert restMembers;
        }

        // Mark the first contact as the household primary contact.
        // Do not hard-code record type Ids; the Account is already the
        // NPSP HH_Account created above.
        Account hh = new Account(
            Id = householdId,
            npe01__One2OneContact__c = firstMember.Id
        );
        update hh;

        return householdId;
    }
}
