public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            if (r == null) {
                continue;
            }
            if (r.opportunityId != null) {
                oppIds.add(r.opportunityId);
            }
            if (r.contactId != null) {
                contactIds.add(r.contactId);
            }
        }

        // SOQL 1: Opportunities
        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>();
        if (!oppIds.isEmpty()) {
            for (Opportunity o : [
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :oppIds
            ]) {
                oppById.put(o.Id, o);
            }
        }

        // SOQL 2: existing OpportunityContactRoles for these opps/contacts
        Map<String, List<OpportunityContactRole>> ocrsByKey = new Map<String, List<OpportunityContactRole>>();
        if (!oppIds.isEmpty() && !contactIds.isEmpty()) {
            for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role
                FROM OpportunityContactRole
                WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
            ]) {
                String k = makeKey(ocr.OpportunityId, ocr.ContactId);
                if (!ocrsByKey.containsKey(k)) {
                    ocrsByKey.put(k, new List<OpportunityContactRole>());
                }
                ocrsByKey.get(k).add(ocr);
            }
        }

        // SOQL 3: existing partial soft credits
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        if (!oppIds.isEmpty() && !contactIds.isEmpty()) {
            for (npsp__Partial_Soft_Credit__c p : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                       npsp__Role_Name__c, npsp__Contact_Role_ID__c
                FROM npsp__Partial_Soft_Credit__c
                WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
            ]) {
                String k = makeKey(p.npsp__Opportunity__c, p.npsp__Contact__c);
                if (!pscsByKey.containsKey(k)) {
                    pscsByKey.put(k, new List<npsp__Partial_Soft_Credit__c>());
                }
                pscsByKey.get(k).add(p);
            }
        }

        // ---- Validate whole call before any DML ----
        for (SoftCreditRequest r : requests) {
            if (r == null) {
                continue;
            }
            if (r.opportunityId == null || r.contactId == null) {
                throw new SoftCreditException('Opportunity and Contact are required.');
            }
            Opportunity o = oppById.get(r.opportunityId);
            if (o == null) {
                throw new SoftCreditException('Opportunity not found: ' + r.opportunityId);
            }
            if (o.npsp__Primary_Contact__c != null && o.npsp__Primary_Contact__c == r.contactId) {
                throw new SoftCreditException('Contact is the primary contact on the opportunity.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }
            if (o.Amount != null && r.amount > o.Amount) {
                throw new SoftCreditException('Amount cannot exceed the opportunity amount.');
            }
            if (String.isBlank(r.role)) {
                throw new SoftCreditException('Role is required.');
            }
        }

        // ---- Build OCR upserts (insert + update in one statement) ----
        Map<String, OpportunityContactRole> targetOcrByKey = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> ocrUpserts = new List<OpportunityContactRole>();
        List<SObject> toDelete = new List<SObject>();

        for (SoftCreditRequest r : requests) {
            if (r == null) {
                continue;
            }
            String k = makeKey(r.opportunityId, r.contactId);
            if (targetOcrByKey.containsKey(k)) {
                continue;
            }
            List<OpportunityContactRole> existing = ocrsByKey.get(k);
            if (existing == null) {
                existing = new List<OpportunityContactRole>();
            }
            OpportunityContactRole keep = null;
            for (OpportunityContactRole e : existing) {
                if (e.Role == r.role) {
                    keep = e;
                    break;
                }
            }
            if (keep != null) {
                // Keep one with matching role, delete any others
                targetOcrByKey.put(k, keep);
                for (OpportunityContactRole e : existing) {
                    if (e.Id != keep.Id) {
                        toDelete.add(e);
                    }
                }
            } else if (!existing.isEmpty()) {
                keep = existing[0];
                keep.Role = r.role;
                ocrUpserts.add(keep);
                targetOcrByKey.put(k, keep);
                for (Integer i = 1; i < existing.size(); i++) {
                    toDelete.add(existing[i]);
                }
            } else {
                OpportunityContactRole n = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
                ocrUpserts.add(n);
                targetOcrByKey.put(k, n);
            }
        }

        // DML 1: upsert OCRs (inserts + updates together)
        if (!ocrUpserts.isEmpty()) {
            upsert ocrUpserts;
        }

        // ---- Build PSC upserts (insert + update in one statement) ----
        List<npsp__Partial_Soft_Credit__c> pscUpserts = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest r : requests) {
            if (r == null) {
                continue;
            }
            String k = makeKey(r.opportunityId, r.contactId);
            OpportunityContactRole targetOcr = targetOcrByKey.get(k);
            List<npsp__Partial_Soft_Credit__c> existingPscs = pscsByKey.get(k);
            if (existingPscs != null && !existingPscs.isEmpty()) {
                npsp__Partial_Soft_Credit__c keep = existingPscs[0];
                keep.npsp__Opportunity__c = r.opportunityId;
                keep.npsp__Contact__c = r.contactId;
                keep.npsp__Amount__c = r.amount;
                keep.npsp__Role_Name__c = r.role;
                keep.npsp__Contact_Role_ID__c = targetOcr != null ? (String)targetOcr.Id : null;
                pscUpserts.add(keep);
                for (Integer i = 1; i < existingPscs.size(); i++) {
                    toDelete.add(existingPscs[i]);
                }
                // Prevent double-adding if duplicate keys existed (spec says no dupes, but guard)
                pscsByKey.put(k, new List<npsp__Partial_Soft_Credit__c>{ keep });
            } else {
                npsp__Partial_Soft_Credit__c n = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId,
                    npsp__Amount__c = r.amount,
                    npsp__Role_Name__c = r.role,
                    npsp__Contact_Role_ID__c = targetOcr != null ? (String)targetOcr.Id : null
                );
                pscUpserts.add(n);
                pscsByKey.put(k, new List<npsp__Partial_Soft_Credit__c>{ n });
            }
        }

        // DML 2: delete duplicate OCRs / PSCs if any
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // If we deleted extra OCRs, the surviving OCR Id is unchanged, so PSC links remain valid.
        // DML 3: upsert PSCs (inserts + updates together)
        if (!pscUpserts.isEmpty()) {
            upsert pscUpserts;
        }
    }

    private static String makeKey(Id oppId, Id contactId) {
        return String.valueOf(oppId) + ':' + String.valueOf(contactId);
    }
}
