global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_MIN = 5000;
    private static final String WON_STAGE = 'Closed Won';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return null;
        }

        Map<Id, SObject> oldMap = null;
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            oldMap = new Map<Id, SObject>(oldlist);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject so : newlist) {
            Opportunity newOpp = (Opportunity) so;

            Boolean nowQualifies = isQualified(newOpp);
            if (!nowQualifies) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldMap != null && oldMap.containsKey(newOpp.Id)
                    ? (Opportunity) oldMap.get(newOpp.Id)
                    : null;
                // If we have old value and it already qualified, do not create another task
                if (oldOpp != null && isQualified(oldOpp)) {
                    continue;
                }
                // If old is missing, fall through and create (treated as newly qualified)
            }

            Task t = new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = newOpp.Id,
                WhoId = newOpp.npsp__Primary_Contact__c,
                OwnerId = newOpp.OwnerId
            );
            if (newOpp.CloseDate != null) {
                t.ActivityDate = newOpp.CloseDate.addDays(3);
            }
            tasksToInsert.add(t);
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return null;
    }

    private Boolean isQualified(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        if (opp.StageName != WON_STAGE) {
            return false;
        }
        if (opp.Amount == null || opp.Amount < MAJOR_GIFT_MIN) {
            return false;
        }
        return true;
    }
}
