```apex
public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Collect non-null Ids into a List for chunking.
        List<Id> cleanIds = new List<Id>();
        for (Id recId : recordIds) {
            if (recId != null) {
                cleanIds.add(recId);
            }
        }
        if (cleanIds.isEmpty()) {
            return result;
        }

        Id currentUserId = UserInfo.getUserId();

        // UserRecordAccess supports at most 200 RecordIds per query,
        // so chunk to stay within limits and query count (2000 Ids = 10 queries).
        Integer chunkSize = 200;
        for (Integer i = 0; i < cleanIds.size(); i += chunkSize) {
            Integer endIndex = Math.min(i + chunkSize, cleanIds.size());
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < endIndex; j++) {
                chunk.add(cleanIds[j]);
            }
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
