public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        checkDuplicates(newContacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        Map<Id, Contact> oldMap = new Map<Id, Contact>((List<Contact>) triggerOld);
        checkDuplicates(newContacts, oldMap);
    }

    private void checkDuplicates(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> candidateIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact oldC = oldMap.get(c.Id);
                if (oldC != null && equalsIgnoreCase(oldC.Email, c.Email) && oldC.AccountId == c.AccountId) {
                    continue;
                }
            }
            candidates.add(c);
            accountIds.add(c.AccountId);
            if (c.Id != null) {
                candidateIds.add(c.Id);
            }
        }
        if (candidates.isEmpty()) {
            return;
        }

        Set<String> existingKeys = new Set<String>();
        for (Contact e : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email != NULL AND Id NOT IN :candidateIds
        ]) {
            if (e.AccountId != null && !String.isBlank(e.Email)) {
                existingKeys.add(key(e.AccountId, e.Email));
            }
        }

        Set<String> seenKeys = new Set<String>();
        for (Contact c : candidates) {
            String k = key(c.AccountId, c.Email);
            if (existingKeys.contains(k) || seenKeys.contains(k)) {
                c.addError(ERROR_MESSAGE);
            } else {
                seenKeys.add(k);
            }
        }
    }

    private static String key(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }

    private static Boolean equalsIgnoreCase(String a, String b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        return a.toLowerCase() == b.toLowerCase();
    }
}
