public inherited sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        rollup(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        for (SObject so : triggerOld) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        rollup(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerOld) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        rollup(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        rollup(accountIds);
    }

    private static void rollup(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id accId : accountIds) {
            counts.put(accId, 0);
        }
        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            counts.put((Id)ar.get('accId'), (Integer)ar.get('cnt'));
        }
        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            toUpdate.add(new Account(Id = accId, FB_Open_Case_Count__c = counts.get(accId)));
        }
        update toUpdate;
    }
}
