                continue;
            }
            if (String.isNotBlank(c.MailingStreet)
                || String.isNotBlank(c.MailingCity)
                || String.isNotBlank(c.MailingPostalCode)
                || String.isNotBlank(c.MailingCountry)) {
                continue;
            }
            Account parent = accountsById.get(c.AccountId);
            if (parent == null) {
                continue;
            }
            c.MailingStreet = parent.BillingStreet;
            c.MailingCity = parent.BillingCity;
            c.MailingPostalCode = parent.BillingPostalCode;
            c.MailingCountry = parent.BillingCountry;
        }
